          "path": "/Users/shaokaiwen/Library/Mobile Documents/com~apple~CloudDocs/TEACHER/INC/Powerpoint/Chapter 1 - Data representation/T3 Binary shifts and twos complement/Chapter1_Data representation_T3_PPT_2024-9-27.pptx",
