          "path": "/Users/shaokaiwen/Library/Mobile Documents/com~apple~CloudDocs/TEACHER/INC/Powerpoint/Chapter 1 - Data representation/T4 ASCII and Unicode/Chapter1_Data representation_T4_PPT_2024-9-27.pptx",
