                "Uses cheap secondary storage on the hard disk/SSD",
                "Allows the running of programs too large to fit in main memory",
                "Prevents error messages saying ‘out of memory’ – the programs and files will still open",
                "Disadvantages",
                "Accessing virtual memory is very slow",
