          "path": "/Users/shaokaiwen/Library/Mobile Documents/com~apple~CloudDocs/TEACHER/INC/Powerpoint/Chapter 3 Hardware/Chapter 3.1 Computer architecture/T2 CPU performance and busses/Chapter3.1_Hardware_T2_PPT_2024-11-4.pptx",
