          "path": "/Users/shaokaiwen/Library/Mobile Documents/com~apple~CloudDocs/TEACHER/INC/Powerpoint/Chapter 6 - Automated-and-emerging-technologies/T3 Artificial intelligence/T3 Artificial intelligence18-09-2024.pptx",
          "thumbnail": "../assets/lesson-thumbnails/chapter-6-topic-3-t3-artificial-intelligence18-09-2024.png",
