                "Asyntax error is one where the code written doesn’t conform to the rules of the language",
                "The compiler doesn’t know how to translate the program into machine code so will give the programmer a syntax error",
                "The program cannot be run until all syntax errors are fixed",
                "Which of the errors in the starter were syntax errors?",
                "INPUT Num1 INPUT Num2 INPUT Num3 MaxNum  0",
                "IF Num1 >= Num2 AD Num1 >= Num3 THEN MaxNum  Num3 ELSE IF Num2 >= Num3 THEN MaxNum  Num2 ELSE MaxNum  Num3 ENDIF ENDIF OUTPUT \"Max number:, maxNum",
