                "IF Num1 >= Num2 AD Num1 >= Num3 THEN MaxNum  Num3 ELSE IF Num2 >= Num3 THEN MaxNum  Num2 ELSE MaxNum  Num3 ENDIF ENDIF OUTPUT \"Max number:, maxNum",
