                "OUTPUT \"menu\" OUTPUT \"1: New file\" OUTPUT \"2: Edit file\" OUTPUT \"3: Delete file\" OUTPUT \"4: Quit\" OUTPUT \"5: Show menu\" choice ← USERINPUT",
