                "This makes code easier to read and understand",
                "INPUT a INPUT b INPUT c d  a + b + c e  d / 3 OUPTUT e",
                "INPUT num1 INPUT num2 INPUT num3 total  num1 + num2 + num3 average  total / 3 OUTPUT average",
