              "number": 16,
              "title": "Processing a 2D array",
              "lines": [
                "Find and display the total mark for each student:",
                "Student1 12 14 8 7 17",
                "Student2 6 8 5 3 13",
                "Student3 16 15 9 10 18",
                "FOR s ← 1 TO 3 StudentTotal ← 0",
                "FOR m ← 1 TO 5",
                "StudentTotal ← StudentTotal + Mark[s, m]",
                "NEXT m",
                "OUTPUT StudentTotal",
                "NEXT s"
              ]
